def evaluate_sec270aa_immunity(is_misreporting: bool, demand_paid_within_time: bool, appeal_waived: bool, form68_filed_within_1m: bool) -> dict:
    if is_misreporting:
        return {
            "immunity_granted": False,
            "status": "BARRED under Sec 270AA(3): Immunity cannot be granted for cases involving Section 270A(8)/(9) Misreporting"
        }

    conditions_met = demand_paid_within_time and appeal_waived and form68_filed_within_1m

    if conditions_met:
        return {
            "immunity_granted": True,
            "status": "IMMUNITY GRANTED under Section 270AA(4)",
            "benefits": [
                "100% waiver of penalty under Section 270A",
                "Total immunity from prosecution under Section 276C / 276CCC",
                "Final settlement and closure of assessment"
            ]
        }
    else:
        reasons = []
        if not demand_paid_within_time:
            reasons.append("Demand not paid within 30-day window")
        if not appeal_waived:
            reasons.append("Appeal filed before CIT(Appeals)")
        if not form68_filed_within_1m:
            reasons.append("Form 68 not filed within 1 month")
        return {
            "immunity_granted": False,
            "status": f"REJECTED: Preconditions violated ({', '.join(reasons)})"
        }

imm_res = evaluate_sec270aa_immunity(is_misreporting=False, demand_paid_within_time=True, appeal_waived=True, form68_filed_within_1m=True)
print(f"Immunity Granted: {imm_res['immunity_granted']}")
print(f"Outcome: {imm_res['status']}")
if imm_res['immunity_granted']:
    for b in imm_res['benefits']:
        print(f"  -> {b}")

def evaluate_criminal_prosecution(tax_evaded_inr: float, is_willful_attempt: bool, can_compound: bool) -> dict:
    if not is_willful_attempt:
        return {"prosecution_initiated": False, "status": "No mens rea: Genuine interpretation dispute; prosecution barred"}

    threshold_25_lakh = 2500000.0  # Rs 25 Lakh

    if tax_evaded_inr > threshold_25_lakh:
        charge = "Section 276C(1)(i): Rigorous Imprisonment (Min 6 months, Max 7 years) + Fine"
        imprisonment_bracket = "6 Months to 7 Years"
    else:
        charge = "Section 276C(1)(ii): Rigorous Imprisonment (Min 3 months, Max 2 years) + Fine"
        imprisonment_bracket = "3 Months to 2 Years"

    if can_compound:
        # Standard CBDT Compounding Fee: ~50% of tax evaded
        compounding_fee = tax_evaded_inr * 0.50
        resolution = f"Eligible for Compounding under Sec 279(2) upon payment of INR {compounding_fee:,.2f}"
    else:
        compounding_fee = 0.0
        resolution = "Non-compoundable / Trial must proceed in Special Economic Offences Court"

    return {
        "prosecution_initiated": True,
        "tax_evaded_inr": tax_evaded_inr,
        "statutory_charge": charge,
        "imprisonment_exposure": imprisonment_bracket,
        "compounding_resolution": resolution,
        "compounding_fee_inr": compounding_fee
    }

pros_res = evaluate_criminal_prosecution(tax_evaded_inr=10000000.0, is_willful_attempt=True, can_compound=True)
print(f"Prosecution Initiated: {pros_res['prosecution_initiated']}")
print(f"Statutory Charge: {pros_res['statutory_charge']}")
print(f"Imprisonment Exposure: {pros_res['imprisonment_exposure']}")
print(f"Compounding Option: {pros_res['compounding_resolution']}")
